from __future__ import annotations

from decimal import Decimal, ROUND_DOWN


class Group:
    def __init__(self, members: list[str]) -> None:
        self.members = list(members)
        self._balances: dict[str, Decimal] = {m: Decimal("0") for m in members}

    def add_expense(self, payer: str, amount: float,
                    participants: list[str] | None = None) -> None:
        """Record that `payer` paid `amount` on behalf of `participants`."""
        if amount <= 0:
            raise ValueError("amount must be positive")
        if payer not in self._balances:
            raise ValueError(f"unknown payer: {payer}")

        amt = Decimal(str(amount)).quantize(Decimal("0.01"))
        if participants is None:
            participants = list(self.members)
        else:
            participants = list(participants)
        for p in participants:
            if p not in self._balances:
                raise ValueError(f"unknown participant: {p}")

        n = len(participants)
        if n == 0:
            return

        # Split equally to the cent; leftover cents borne by the payer.
        per = (amt / n).quantize(Decimal("0.01"), rounding=ROUND_DOWN)
        total_share = per * n
        leftover = amt - total_share  # amount borne by payer

        self._balances[payer] += amt
        for p in participants:
            self._balances[p] -= per
        # Payer also bears the leftover on top of their own share.
        self._balances[payer] -= leftover

    def balances(self) -> dict[str, float]:
        """Net balance per member. Positive = member is owed, negative = owes."""
        return {m: float(v) for m, v in self._balances.items()}

    def settle_up(self) -> list[tuple[str, str, float]]:
        """Payments that settle the group, as (debtor, creditor, amount)."""
        creditors = []
        debtors = []
        for m, v in self._balances.items():
            if v > 0:
                creditors.append([m, v])
            elif v < 0:
                debtors.append([m, -v])

        creditors.sort(key=lambda x: x[1], reverse=True)
        debtors.sort(key=lambda x: x[1], reverse=True)

        payments: list[tuple[str, str, float]] = []
        ci = 0
        di = 0
        while ci < len(creditors) and di < len(debtors):
            cname, camt = creditors[ci]
            dname, damt = debtors[di]
            pay = min(camt, damt)
            if pay >= Decimal("1.00"):
                payments.append((dname, cname, float(pay)))
            camt -= pay
            damt -= pay
            creditors[ci][1] = camt
            debtors[di][1] = damt
            if camt == 0:
                ci += 1
            if damt == 0:
                di += 1
        return payments
